WITH base AS (SELECT *, DATEDIFF(delivered_date, shipped_date) AS days_shipped_date_to_delivered_date FROM shipments WHERE status IN ('DELIVERED', 'LOST')), agg AS (SELECT carrier, MIN(days_shipped_date_to_delivered_date) AS min_days_shipped_date_to_delivered_date, AVG(days_shipped_date_to_delivered_date) AS avg_days_shipped_date_to_delivered_date FROM base GROUP BY carrier) SELECT * FROM agg ORDER BY min_days_shipped_date_to_delivered_date;
